import { createAudioPlayer, type AudioPlayer } from 'expo-audio';
import * as Speech from 'expo-speech';
import { useSyncExternalStore } from 'react';

import { audioKey } from '@/lib/audio-key';
import { supabase } from '@/lib/supabase';
import { audioSpeed } from '@/providers/display-preferences';

/**
 * Word and sentence audio: a recorded neural voice (Azure, generated by scripts/generate-audio.ts)
 * when there is a clip for the text, otherwise the device's built-in Chinese voice.
 * Callers use `useSpeech()` / `speakChinese()`; the learner's speed setting applies to both.
 */

// --- Which texts have recorded clips (audio/index.json, loaded once) -------------------------

let index: Promise<Set<string>> | null = null;
function clipIndex(): Promise<Set<string>> {
  index ??= fetch(supabase.storage.from('audio').getPublicUrl('index.json').data.publicUrl)
    .then((r) => (r.ok ? r.json() : []))
    .then((keys: string[]) => new Set(keys))
    .catch(() => {
      index = null; // try again next time
      return new Set<string>();
    });
  return index;
}

export function clipUrl(text: string): string {
  return supabase.storage.from('audio').getPublicUrl(`clips/${audioKey(text)}.mp3`).data.publicUrl;
}

export async function hasClip(text: string): Promise<boolean> {
  return (await clipIndex()).has(audioKey(text));
}

// --- Device voice ----------------------------------------------------------------------------

let voiceLookup: Promise<string | undefined> | null = null;

/** Best Mandarin (mainland) voice: enhanced quality first, then any zh-CN, then any Chinese. */
function chineseVoice(): Promise<string | undefined> {
  // Browsers without voices never answer; give up after a moment and use the default voice.
  const timeout = new Promise<Speech.Voice[]>((resolve) => setTimeout(() => resolve([]), 1500));
  voiceLookup ??= Promise.race([Speech.getAvailableVoicesAsync(), timeout])
    .then((voices) => {
      const lang = (v: Speech.Voice) => v.language.replace('_', '-').toLowerCase();
      const mainland = voices.filter(
        (v) => lang(v) === 'zh-cn' || lang(v).startsWith('zh-hans') || lang(v) === 'cmn-cn',
      );
      const best =
        mainland.find((v) => v.quality === Speech.VoiceQuality.Enhanced) ??
        mainland[0] ??
        voices.find((v) => lang(v).startsWith('zh') && !lang(v).includes('hk'));
      return best?.identifier;
    })
    .catch(() => undefined);
  return voiceLookup;
}

// --- What's playing (so only that button shows as active) -----------------------------------

let playing: string | null = null;
const listeners = new Set<() => void>();
function setPlaying(id: string | null) {
  playing = id;
  listeners.forEach((l) => l());
}
function subscribe(l: () => void) {
  listeners.add(l);
  return () => listeners.delete(l);
}

// Bumps on every play, so callbacks from an earlier (stopped) sound can't clear a newer one.
let turn = 0;
let player: AudioPlayer | null = null;

function stopPlayer() {
  if (!player) return;
  try {
    player.pause();
    player.remove();
  } catch {
    // already released
  }
  player = null;
}

export async function stopSpeech() {
  turn++;
  stopPlayer();
  setPlaying(null);
  await Speech.stop();
}

/**
 * Plays a file or URL (a recorded clip, or the learner's own recording). Calls `failed` if it can't
 * be loaded (e.g. offline), so the caller can fall back to the device voice.
 */
function playUri(uri: string, mine: number, done: () => void, failed: () => void) {
  const p = createAudioPlayer({ uri }, { updateInterval: 100 });
  player = p;
  p.addListener('playbackStatusUpdate', (status) => {
    if (mine !== turn) return;
    if (status.error) {
      stopPlayer();
      failed();
    } else if (status.didJustFinish) {
      stopPlayer();
      done();
    }
  });
  p.setPlaybackRate(audioSpeed(), 'high');
  p.play();
}

/**
 * Says `text` in Chinese. `fallback` is what the device voice reads when there is no clip
 * (e.g. the character for a tone-trainer syllable like "tone:ma3").
 */
export async function speakChinese(text: string, id = text, fallback = text) {
  const mine = ++turn;
  stopPlayer();
  await Speech.stop();
  const recorded = await hasClip(text);
  const voice = recorded ? undefined : await chineseVoice();
  if (mine !== turn) return; // another button was pressed meanwhile
  setPlaying(id);
  const done = () => {
    if (mine === turn) setPlaying(null);
  };
  const deviceVoice = () => {
    if (mine !== turn) return;
    Speech.speak(fallback, {
      language: 'zh-CN',
      voice,
      rate: 0.85 * audioSpeed(),
      // iPhone: let the system manage speech audio, so it plays even with the silent switch on.
      useApplicationAudioSession: false,
      onDone: done,
      onStopped: done,
      onError: done,
    });
  };
  if (recorded) playUri(clipUrl(text), mine, done, deviceVoice);
  else deviceVoice();
}

/** Plays the learner's own recording (a local file or blob URL). */
export async function playRecording(uri: string, id = 'my-recording') {
  const mine = ++turn;
  stopPlayer();
  await Speech.stop();
  setPlaying(id);
  const done = () => {
    if (mine === turn) setPlaying(null);
  };
  playUri(uri, mine, done, done);
}

export function useSpeech() {
  const current = useSyncExternalStore(
    subscribe,
    () => playing,
    () => null,
  );
  return { playingId: current, speak: speakChinese, stop: stopSpeech };
}
